INSERT INTO tenant_recording_policies (tenant_id,recording_consent_required,consent_source,block_link_if_missing_consent,allow_customer_visibility,redact_transcript_before_ai,allow_ai_summary,recording_retention_days,allow_manual_upload) VALUES
('06a270ba-09fc-7752-8000-0b10a0c66562',true,'teams_notice',false,false,true,true,365,true)
INSERT INTO rca_policies (id,tenant_id,name,description,status,conditions,outputs,priority,created_by) VALUES
('5e6142e2-aeb8-5858-8539-6db9db41aec7','06a270ba-09fc-7752-8000-0b10a0c66562','Major incident postmortem','SEV1/SEV2 incidents always require a governed RCA.','active','[{"field": "incident.severity", "op": "in", "value": ["SEV1", "SEV2"]}]'::jsonb,'{"owner_role": "team_lead", "approver_role": "manager", "due_days": 3, "required_evidence_types": ["primary_ticket_linked", "customer_impact_documented", "timeline_completed", "recording_linked_if_exists", "recording_summary_reviewed", "logs_alerts_linked", "service_asset_impact_linked", "sla_breach_evidence_linked", "customer_communication_captured", "corrective_actions_created", "approval_comments_present"]}'::jsonb,10,'10149a68-a6be-5380-ad66-e55f26d6adac'),
('fb2d26de-9c8d-5ae5-9cfa-01605f527edf','06a270ba-09fc-7752-8000-0b10a0c66562','SLA breach on high/critical ticket','A breached SLA on a high or critical ticket triggers an RCA owned by the assignee.','active','[{"field": "ticket.priority", "op": "in", "value": ["high", "critical"]}, {"field": "ticket.sla_breached", "op": "eq", "value": true}]'::jsonb,'{"owner_role": "agent", "approver_role": "team_lead", "due_days": 5}'::jsonb,20,'10149a68-a6be-5380-ad66-e55f26d6adac'),
('5a3cf556-99e2-5ddf-95ee-71d45adc435c','06a270ba-09fc-7752-8000-0b10a0c66562','Repeat incident review','Three or more recurrences of the same issue require a review, but may be waived by a manager if the root cause is already known and resolved.','active','[{"field": "ticket.tag", "op": "eq", "value": "recurring"}]'::jsonb,'{"owner_role": "agent", "approver_role": "manager", "due_days": 7}'::jsonb,30,'10149a68-a6be-5380-ad66-e55f26d6adac')
INSERT INTO support_recordings (id,tenant_id,source_type,source_recording_id,source_meeting_id,source_drive_id,source_item_id,recording_url,transcript_url,title,description,started_at,ended_at,duration_seconds,organizer_user_id,organizer_email,customer_contact_name,customer_contact_email,participants,consent_status,sensitivity,access_policy,retention_expires_at,storage_mode,storage_key,status,ai_summary_status,ai_summary,ai_action_items,created_by,created_at,updated_at) VALUES
('77f13e01-b158-5eea-bbea-2337c23f2b28','06a270ba-09fc-7752-8000-0b10a0c66562','teams','demo-77f13e01',NULL,NULL,NULL,'https://teams.demo/recordings/77f13e01',NULL,'Laptop won''t boot — troubleshooting call w/ Casey Brooks','Screen-share to diagnose a Windows Update stuck at boot. Tried safe mode, then a rollback.','2026-07-23T13:00:00','2026-07-23T13:22:00',1320,'fa4021fd-1b19-5f85-897f-ecfaa6cd0949','ag1@blue.demo','Casey Brooks','casey.brooks@blue.demo','[{"name": "Support Agent", "email": "ag1@blue.demo", "role": "organizer", "internal": true}, {"name": "Casey Brooks", "email": "casey.brooks@blue.demo", "role": "customer", "internal": false}]'::jsonb,'captured_in_teams','normal','ticket_team_only','2027-07-29T12:00:00','external_reference',NULL,'linked','completed','Customer''s laptop hung on a Windows Update splash screen after a forced restart. Agent booted into safe mode, confirmed the update service was corrupted, then rolled back the pending update and re-applied it cleanly. Laptop boots normally; no data loss. No follow-up needed.','[{"title": "Confirm update rollback didn''t affect BitLocker key escrow", "owner_suggestion": "ag1", "confidence": 0.62}]'::jsonb,'fa4021fd-1b19-5f85-897f-ecfaa6cd0949','2026-07-23T13:00:00','2026-07-29T06:00:00'),
('fd819cac-487b-561a-bb5e-9b1199a91359','06a270ba-09fc-7752-8000-0b10a0c66562','teams','demo-fd819cac',NULL,NULL,NULL,'https://teams.demo/recordings/fd819cac',NULL,'3rd floor packet loss — on-site diagnostic w/ Taylor Okafor','Screen-share of switch diagnostics while investigating intermittent packet loss.','2026-07-20T14:00:00','2026-07-20T14:41:00',2460,'211a6f18-896e-57a8-84de-e28594e57387','ag3@blue.demo',NULL,NULL,'[{"name": "Support Agent", "email": "ag3@blue.demo", "role": "organizer", "internal": true}]'::jsonb,'manually_confirmed','normal','ticket_team_only','2027-07-29T12:00:00','external_reference',NULL,'linked','completed','Agent captured a packet trace on the 3rd-floor switch stack during an active loss event and identified a flapping uplink port. A temporary reroute restored stable connectivity; root cause traced to a failing SFP module on switch port 14, scheduled for replacement.','[{"title": "Replace SFP module on switch port 14", "owner_suggestion": "ag3", "confidence": 0.88}]'::jsonb,'211a6f18-896e-57a8-84de-e28594e57387','2026-07-20T14:00:00','2026-07-29T06:00:00'),
('938b7a52-c04b-56b5-8d70-37265c015e3d','06a270ba-09fc-7752-8000-0b10a0c66562','sharepoint','demo-938b7a52',NULL,NULL,NULL,'https://sharepoint.demo/recordings/938b7a52',NULL,'Payroll slowness review — includes finance walkthrough','Customer shared their screen to demo the slowdown; briefly showed a payroll record with an account number visible.','2026-07-27T15:00:00','2026-07-27T15:18:00',1080,'42649ec3-42f1-5ec2-b238-8e5376c955db','ag2@blue.demo','Devin Flores','devin.flores@blue.demo','[{"name": "Support Agent", "email": "ag2@blue.demo", "role": "organizer", "internal": true}, {"name": "Devin Flores", "email": "devin.flores@blue.demo", "role": "customer", "internal": false}]'::jsonb,'disputed','contains_pii','manager_only','2027-07-29T12:00:00','external_reference',NULL,'needs_review','skipped_no_consent',NULL,NULL,'42649ec3-42f1-5ec2-b238-8e5376c955db','2026-07-27T15:00:00','2026-07-29T06:00:00'),
('fe4a959e-2cbc-573b-bd03-7a5939cb592e','06a270ba-09fc-7752-8000-0b10a0c66562','onedrive','demo-fe4a959e',NULL,NULL,NULL,'https://onedrive.demo/recordings/fe4a959e',NULL,'VPN concentrator outage — infra bridge (customer leg)','Customer-facing leg of the VPN outage bridge; organizer''s OneDrive link expired before it could be archived.','2026-07-24T16:00:00','2026-07-24T16:35:00',2100,'211a6f18-896e-57a8-84de-e28594e57387','ag3@blue.demo',NULL,NULL,'[{"name": "Support Agent", "email": "ag3@blue.demo", "role": "organizer", "internal": true}]'::jsonb,'missing','normal','ticket_team_only','2027-07-29T12:00:00','external_reference',NULL,'inaccessible','not_requested',NULL,NULL,'211a6f18-896e-57a8-84de-e28594e57387','2026-07-24T16:00:00','2026-07-29T06:00:00'),
('8f3d40c3-a953-5c7a-ac2d-13f9f5361cef','06a270ba-09fc-7752-8000-0b10a0c66562','teams','demo-8f3d40c3',NULL,NULL,NULL,'https://teams.demo/recordings/8f3d40c3',NULL,'Payments API outage — incident bridge (all-hands)','Full incident bridge call: detection, rollback decision, and recovery confirmation.','2026-06-27T12:05:00','2026-06-27T13:05:00',3600,'10149a68-a6be-5380-ad66-e55f26d6adac','mgr@blue.demo',NULL,NULL,'[{"name": "Support Agent", "email": "mgr@blue.demo", "role": "organizer", "internal": true}]'::jsonb,'not_required','normal','ticket_team_only','2027-07-29T12:00:00','external_reference',NULL,'linked','completed','Incident bridge for the Payments API outage: on-call engineer identified a bad config deploy within 6 minutes of paging, IC approved an immediate rollback, and payments traffic recovered within ~40 minutes. No canary stage existed to catch the bad config pre-rollout; action item raised to add one.','[{"title": "Add canary stage to payments deploy pipeline", "owner_suggestion": "lead", "confidence": 0.91}]'::jsonb,'10149a68-a6be-5380-ad66-e55f26d6adac','2026-06-27T12:05:00','2026-07-29T06:00:00')
