INSERT INTO incident_retrospectives (id,tenant_id,incident_id,summary,status,is_rca_governed,source_type,source_ticket_id,rca_number,severity,owner_id,approver_id,team_id,trigger_policy_id,previous_status,due_at,submitted_at,approved_at,executive_summary,customer_impact,technical_summary,root_cause_statement,root_cause_category,contributing_factor_tags,detection_gap,prevention_plan,lessons_learned,ai_draft_status,ai_confidence,ai_model_version,created_by) VALUES
('455a909e-0a44-5a15-8a91-8f738a0e31ce','06a270ba-09fc-7752-8000-0b10a0c66562',NULL,'Recurring 3rd-floor packet loss traced to a failing SFP module.','actions_in_progress',true,'ticket','46ff3af3-249e-5795-b1be-d6df1670a3d1','RCA-2026-0002','sev3','211a6f18-896e-57a8-84de-e28594e57387','10149a68-a6be-5380-ad66-e55f26d6adac','0d9630c6-6659-5bfe-8201-72f054986bd8','fb2d26de-9c8d-5ae5-9cfa-01605f527edf','approved','2026-07-25T12:00:00','2026-07-20T12:00:00','2026-07-21T12:00:00','Third recurrence of packet loss on the 3rd-floor switch stack; SLA breached before root cause was found.','Intermittent VoIP/video drops for ~40 staff over 4 days; two dropped customer calls reported.','Packet capture during an active loss event showed a flapping uplink; SFP module on port 14 was degraded, not fully failed, so health checks didn''t catch it.','A degrading (not dead) SFP transceiver caused intermittent link flaps that standard link-up/down monitoring didn''t detect.','environment','["no_proactive_health_check", "hardware_degradation"]'::jsonb,'No signal-quality monitoring on switch uplinks — only up/down state was alerted on.','Add optical signal-strength monitoring to catch degrading transceivers before they flap.','Link up/down monitoring alone misses slow hardware degradation.','completed',0.74,'heuristic-v1','10149a68-a6be-5380-ad66-e55f26d6adac')
