INSERT INTO rca_policies (id,tenant_id,name,description,status,conditions,outputs,priority,created_by) VALUES
('47c1022e-02fd-56fc-bf52-2ff3ec82a7db','7862dc84-72d6-40a9-b2b1-c7c7896bc148','Major incident postmortem','SEV1/SEV2 incidents always require a governed RCA.','active','[{"field": "incident.severity", "op": "in", "value": ["SEV1", "SEV2"]}]'::jsonb,'{"owner_role": "team_lead", "approver_role": "manager", "due_days": 3, "required_evidence_types": ["primary_ticket_linked", "customer_impact_documented", "timeline_completed", "recording_linked_if_exists", "recording_summary_reviewed", "logs_alerts_linked", "service_asset_impact_linked", "sla_breach_evidence_linked", "customer_communication_captured", "corrective_actions_created", "approval_comments_present"]}'::jsonb,10,'82ce8a8d-1bb9-5b4c-bea8-3e2d9c93b049'),
('642519b1-2f5b-59eb-a3f2-37d990ec624c','7862dc84-72d6-40a9-b2b1-c7c7896bc148','SLA breach on high/critical ticket','A breached SLA on a high or critical ticket triggers an RCA owned by the assignee.','active','[{"field": "ticket.priority", "op": "in", "value": ["high", "critical"]}, {"field": "ticket.sla_breached", "op": "eq", "value": true}]'::jsonb,'{"owner_role": "agent", "approver_role": "team_lead", "due_days": 5}'::jsonb,20,'82ce8a8d-1bb9-5b4c-bea8-3e2d9c93b049'),
('d18932ac-2ced-52f2-9ecf-883dd1b7fd55','7862dc84-72d6-40a9-b2b1-c7c7896bc148','Repeat incident review','Three or more recurrences of the same issue require a review, but may be waived by a manager if the root cause is already known and resolved.','active','[{"field": "ticket.tag", "op": "eq", "value": "recurring"}]'::jsonb,'{"owner_role": "agent", "approver_role": "manager", "due_days": 7}'::jsonb,30,'82ce8a8d-1bb9-5b4c-bea8-3e2d9c93b049')
INSERT INTO support_recordings (id,tenant_id,source_type,source_recording_id,source_meeting_id,source_drive_id,source_item_id,recording_url,transcript_url,title,description,started_at,ended_at,duration_seconds,organizer_user_id,organizer_email,customer_contact_name,customer_contact_email,participants,consent_status,sensitivity,access_policy,retention_expires_at,storage_mode,storage_key,status,ai_summary_status,ai_summary,ai_action_items,created_by,created_at,updated_at) VALUES
('0e8ad41c-21af-50bf-a198-834b0049efd9','7862dc84-72d6-40a9-b2b1-c7c7896bc148','teams','demo-0e8ad41c',NULL,NULL,NULL,'https://teams.demo/recordings/0e8ad41c',NULL,'Laptop won''t boot — troubleshooting call w/ Casey Brooks','Screen-share to diagnose a Windows Update stuck at boot. Tried safe mode, then a rollback.','2026-07-23T13:00:00','2026-07-23T13:22:00',1320,'30be9e37-c91f-537d-895c-3656a0c3c353','ag1@piq.demo','Casey Brooks','casey.brooks@piq.demo','[{"name": "Support Agent", "email": "ag1@piq.demo", "role": "organizer", "internal": true}, {"name": "Casey Brooks", "email": "casey.brooks@piq.demo", "role": "customer", "internal": false}]'::jsonb,'captured_in_teams','normal','ticket_team_only','2027-07-29T12:00:00','external_reference',NULL,'linked','completed','Customer''s laptop hung on a Windows Update splash screen after a forced restart. Agent booted into safe mode, confirmed the update service was corrupted, then rolled back the pending update and re-applied it cleanly. Laptop boots normally; no data loss. No follow-up needed.','[{"title": "Confirm update rollback didn''t affect BitLocker key escrow", "owner_suggestion": "ag1", "confidence": 0.62}]'::jsonb,'30be9e37-c91f-537d-895c-3656a0c3c353','2026-07-23T13:00:00','2026-07-29T06:00:00'),
('0a7ff67f-4650-5e69-8857-05899671d7c0','7862dc84-72d6-40a9-b2b1-c7c7896bc148','teams','demo-0a7ff67f',NULL,NULL,NULL,'https://teams.demo/recordings/0a7ff67f',NULL,'3rd floor packet loss — on-site diagnostic w/ Taylor Okafor','Screen-share of switch diagnostics while investigating intermittent packet loss.','2026-07-20T14:00:00','2026-07-20T14:41:00',2460,'95196733-d13c-59f3-8fcd-e713c5d325fe','ag3@piq.demo',NULL,NULL,'[{"name": "Support Agent", "email": "ag3@piq.demo", "role": "organizer", "internal": true}]'::jsonb,'manually_confirmed','normal','ticket_team_only','2027-07-29T12:00:00','external_reference',NULL,'linked','completed','Agent captured a packet trace on the 3rd-floor switch stack during an active loss event and identified a flapping uplink port. A temporary reroute restored stable connectivity; root cause traced to a failing SFP module on switch port 14, scheduled for replacement.','[{"title": "Replace SFP module on switch port 14", "owner_suggestion": "ag3", "confidence": 0.88}]'::jsonb,'95196733-d13c-59f3-8fcd-e713c5d325fe','2026-07-20T14:00:00','2026-07-29T06:00:00'),
('64de4e70-f5f5-5528-8438-954afdc1fe15','7862dc84-72d6-40a9-b2b1-c7c7896bc148','sharepoint','demo-64de4e70',NULL,NULL,NULL,'https://sharepoint.demo/recordings/64de4e70',NULL,'Payroll slowness review — includes finance walkthrough','Customer shared their screen to demo the slowdown; briefly showed a payroll record with an account number visible.','2026-07-27T15:00:00','2026-07-27T15:18:00',1080,'5420160e-f427-53bb-9bf8-a23ced907ba4','ag2@piq.demo','Devin Flores','devin.flores@piq.demo','[{"name": "Support Agent", "email": "ag2@piq.demo", "role": "organizer", "internal": true}, {"name": "Devin Flores", "email": "devin.flores@piq.demo", "role": "customer", "internal": false}]'::jsonb,'disputed','contains_pii','manager_only','2027-07-29T12:00:00','external_reference',NULL,'needs_review','skipped_no_consent',NULL,NULL,'5420160e-f427-53bb-9bf8-a23ced907ba4','2026-07-27T15:00:00','2026-07-29T06:00:00'),
('dba00473-5010-5b67-be6e-61e715471df9','7862dc84-72d6-40a9-b2b1-c7c7896bc148','onedrive','demo-dba00473',NULL,NULL,NULL,'https://onedrive.demo/recordings/dba00473',NULL,'VPN concentrator outage — infra bridge (customer leg)','Customer-facing leg of the VPN outage bridge; organizer''s OneDrive link expired before it could be archived.','2026-07-24T16:00:00','2026-07-24T16:35:00',2100,'95196733-d13c-59f3-8fcd-e713c5d325fe','ag3@piq.demo',NULL,NULL,'[{"name": "Support Agent", "email": "ag3@piq.demo", "role": "organizer", "internal": true}]'::jsonb,'missing','normal','ticket_team_only','2027-07-29T12:00:00','external_reference',NULL,'inaccessible','not_requested',NULL,NULL,'95196733-d13c-59f3-8fcd-e713c5d325fe','2026-07-24T16:00:00','2026-07-29T06:00:00'),
('d3eb43bb-569b-562c-9c1d-46d375a4386c','7862dc84-72d6-40a9-b2b1-c7c7896bc148','teams','demo-d3eb43bb',NULL,NULL,NULL,'https://teams.demo/recordings/d3eb43bb',NULL,'Payments API outage — incident bridge (all-hands)','Full incident bridge call: detection, rollback decision, and recovery confirmation.','2026-06-27T12:05:00','2026-06-27T13:05:00',3600,'82ce8a8d-1bb9-5b4c-bea8-3e2d9c93b049','mgr@piq.demo',NULL,NULL,'[{"name": "Support Agent", "email": "mgr@piq.demo", "role": "organizer", "internal": true}]'::jsonb,'not_required','normal','ticket_team_only','2027-07-29T12:00:00','external_reference',NULL,'linked','completed','Incident bridge for the Payments API outage: on-call engineer identified a bad config deploy within 6 minutes of paging, IC approved an immediate rollback, and payments traffic recovered within ~40 minutes. No canary stage existed to catch the bad config pre-rollout; action item raised to add one.','[{"title": "Add canary stage to payments deploy pipeline", "owner_suggestion": "lead", "confidence": 0.91}]'::jsonb,'82ce8a8d-1bb9-5b4c-bea8-3e2d9c93b049','2026-06-27T12:05:00','2026-07-29T06:00:00')
