INSERT INTO incident_retrospectives (id,tenant_id,incident_id,summary,status,is_rca_governed,source_type,source_ticket_id,rca_number,severity,owner_id,approver_id,team_id,trigger_policy_id,previous_status,due_at,submitted_at,approved_at,executive_summary,customer_impact,technical_summary,root_cause_statement,root_cause_category,contributing_factor_tags,detection_gap,prevention_plan,lessons_learned,ai_draft_status,ai_confidence,ai_model_version,created_by) VALUES
('f320bff8-4d4d-509c-9e92-6db67dd98f0a','7862dc84-72d6-40a9-b2b1-c7c7896bc148',NULL,'Recurring 3rd-floor packet loss traced to a failing SFP module.','actions_in_progress',true,'ticket','47c4fafd-dda8-5b69-8649-eca39f82e0af','RCA-2026-0002','sev3','95196733-d13c-59f3-8fcd-e713c5d325fe','82ce8a8d-1bb9-5b4c-bea8-3e2d9c93b049','f301105e-96ff-5a0b-8543-883f155dfec3','642519b1-2f5b-59eb-a3f2-37d990ec624c','approved','2026-07-25T12:00:00','2026-07-20T12:00:00','2026-07-21T12:00:00','Third recurrence of packet loss on the 3rd-floor switch stack; SLA breached before root cause was found.','Intermittent VoIP/video drops for ~40 staff over 4 days; two dropped customer calls reported.','Packet capture during an active loss event showed a flapping uplink; SFP module on port 14 was degraded, not fully failed, so health checks didn''t catch it.','A degrading (not dead) SFP transceiver caused intermittent link flaps that standard link-up/down monitoring didn''t detect.','environment','["no_proactive_health_check", "hardware_degradation"]'::jsonb,'No signal-quality monitoring on switch uplinks — only up/down state was alerted on.','Add optical signal-strength monitoring to catch degrading transceivers before they flap.','Link up/down monitoring alone misses slow hardware degradation.','completed',0.74,'heuristic-v1','82ce8a8d-1bb9-5b4c-bea8-3e2d9c93b049')
INSERT INTO retro_action_items (id,tenant_id,retro_id,description,title,action_type,priority,owner_id,team_id,due_at,status,verification_method,verified_by,verified_at) VALUES
