INSERT INTO rca_policies (id,tenant_id,name,description,status,conditions,outputs,priority,created_by) VALUES
('22ab5fa7-49c6-5bfa-aef8-3663de037a97','56cc885c-37d4-5dc6-900d-1a7a6defec8b','Major incident postmortem','SEV1/SEV2 incidents always require a governed RCA.','active','[{"field": "incident.severity", "op": "in", "value": ["SEV1", "SEV2"]}]'::jsonb,'{"owner_role": "team_lead", "approver_role": "manager", "due_days": 3, "required_evidence_types": ["primary_ticket_linked", "customer_impact_documented", "timeline_completed", "recording_linked_if_exists", "recording_summary_reviewed", "logs_alerts_linked", "service_asset_impact_linked", "sla_breach_evidence_linked", "customer_communication_captured", "corrective_actions_created", "approval_comments_present"]}'::jsonb,10,'6da32b93-6f3d-5f80-b6e7-69cba3f13e38'),
('04fb5f12-b475-576d-83fe-ce104eda4086','56cc885c-37d4-5dc6-900d-1a7a6defec8b','SLA breach on high/critical ticket','A breached SLA on a high or critical ticket triggers an RCA owned by the assignee.','active','[{"field": "ticket.priority", "op": "in", "value": ["high", "critical"]}, {"field": "ticket.sla_breached", "op": "eq", "value": true}]'::jsonb,'{"owner_role": "agent", "approver_role": "team_lead", "due_days": 5}'::jsonb,20,'6da32b93-6f3d-5f80-b6e7-69cba3f13e38'),
('812748e2-8278-56fe-b7b5-0e8e878fe227','56cc885c-37d4-5dc6-900d-1a7a6defec8b','Repeat incident review','Three or more recurrences of the same issue require a review, but may be waived by a manager if the root cause is already known and resolved.','active','[{"field": "ticket.tag", "op": "eq", "value": "recurring"}]'::jsonb,'{"owner_role": "agent", "approver_role": "manager", "due_days": 7}'::jsonb,30,'6da32b93-6f3d-5f80-b6e7-69cba3f13e38')
INSERT INTO support_recordings (id,tenant_id,source_type,source_recording_id,source_meeting_id,source_drive_id,source_item_id,recording_url,transcript_url,title,description,started_at,ended_at,duration_seconds,organizer_user_id,organizer_email,customer_contact_name,customer_contact_email,participants,consent_status,sensitivity,access_policy,retention_expires_at,storage_mode,storage_key,status,ai_summary_status,ai_summary,ai_action_items,created_by,created_at,updated_at) VALUES
('ce4b7b2e-7330-503e-a556-b2976f8f9e85','56cc885c-37d4-5dc6-900d-1a7a6defec8b','teams','demo-ce4b7b2e',NULL,NULL,NULL,'https://teams.demo/recordings/ce4b7b2e',NULL,'Laptop won''t boot — troubleshooting call w/ Casey Brooks','Screen-share to diagnose a Windows Update stuck at boot. Tried safe mode, then a rollback.','2026-07-23T13:00:00','2026-07-23T13:22:00',1320,'5073456e-2932-5df4-b218-9ce4e34553f1','ag1@acme.demo','Casey Brooks','casey.brooks@acme.demo','[{"name": "Support Agent", "email": "ag1@acme.demo", "role": "organizer", "internal": true}, {"name": "Casey Brooks", "email": "casey.brooks@acme.demo", "role": "customer", "internal": false}]'::jsonb,'captured_in_teams','normal','ticket_team_only','2027-07-29T12:00:00','external_reference',NULL,'linked','completed','Customer''s laptop hung on a Windows Update splash screen after a forced restart. Agent booted into safe mode, confirmed the update service was corrupted, then rolled back the pending update and re-applied it cleanly. Laptop boots normally; no data loss. No follow-up needed.','[{"title": "Confirm update rollback didn''t affect BitLocker key escrow", "owner_suggestion": "ag1", "confidence": 0.62}]'::jsonb,'5073456e-2932-5df4-b218-9ce4e34553f1','2026-07-23T13:00:00','2026-07-29T06:00:00'),
('7e5aa363-326d-537c-87ce-36a7950773b3','56cc885c-37d4-5dc6-900d-1a7a6defec8b','teams','demo-7e5aa363',NULL,NULL,NULL,'https://teams.demo/recordings/7e5aa363',NULL,'3rd floor packet loss — on-site diagnostic w/ Taylor Okafor','Screen-share of switch diagnostics while investigating intermittent packet loss.','2026-07-20T14:00:00','2026-07-20T14:41:00',2460,'ba390f71-e0c1-5cb8-8993-20574d961dac','ag3@acme.demo',NULL,NULL,'[{"name": "Support Agent", "email": "ag3@acme.demo", "role": "organizer", "internal": true}]'::jsonb,'manually_confirmed','normal','ticket_team_only','2027-07-29T12:00:00','external_reference',NULL,'linked','completed','Agent captured a packet trace on the 3rd-floor switch stack during an active loss event and identified a flapping uplink port. A temporary reroute restored stable connectivity; root cause traced to a failing SFP module on switch port 14, scheduled for replacement.','[{"title": "Replace SFP module on switch port 14", "owner_suggestion": "ag3", "confidence": 0.88}]'::jsonb,'ba390f71-e0c1-5cb8-8993-20574d961dac','2026-07-20T14:00:00','2026-07-29T06:00:00'),
('36bd1018-2ca4-5e9e-afbf-40c2fdb87168','56cc885c-37d4-5dc6-900d-1a7a6defec8b','sharepoint','demo-36bd1018',NULL,NULL,NULL,'https://sharepoint.demo/recordings/36bd1018',NULL,'Payroll slowness review — includes finance walkthrough','Customer shared their screen to demo the slowdown; briefly showed a payroll record with an account number visible.','2026-07-27T15:00:00','2026-07-27T15:18:00',1080,'83a1c32e-2426-52b4-b62a-8e16ebdea66b','ag2@acme.demo','Devin Flores','devin.flores@acme.demo','[{"name": "Support Agent", "email": "ag2@acme.demo", "role": "organizer", "internal": true}, {"name": "Devin Flores", "email": "devin.flores@acme.demo", "role": "customer", "internal": false}]'::jsonb,'disputed','contains_pii','manager_only','2027-07-29T12:00:00','external_reference',NULL,'needs_review','skipped_no_consent',NULL,NULL,'83a1c32e-2426-52b4-b62a-8e16ebdea66b','2026-07-27T15:00:00','2026-07-29T06:00:00'),
('aa6939b0-f643-5fe2-9a07-b30aa8596729','56cc885c-37d4-5dc6-900d-1a7a6defec8b','onedrive','demo-aa6939b0',NULL,NULL,NULL,'https://onedrive.demo/recordings/aa6939b0',NULL,'VPN concentrator outage — infra bridge (customer leg)','Customer-facing leg of the VPN outage bridge; organizer''s OneDrive link expired before it could be archived.','2026-07-24T16:00:00','2026-07-24T16:35:00',2100,'ba390f71-e0c1-5cb8-8993-20574d961dac','ag3@acme.demo',NULL,NULL,'[{"name": "Support Agent", "email": "ag3@acme.demo", "role": "organizer", "internal": true}]'::jsonb,'missing','normal','ticket_team_only','2027-07-29T12:00:00','external_reference',NULL,'inaccessible','not_requested',NULL,NULL,'ba390f71-e0c1-5cb8-8993-20574d961dac','2026-07-24T16:00:00','2026-07-29T06:00:00'),
('3c3cf122-5ef6-538f-98d2-0455865ac389','56cc885c-37d4-5dc6-900d-1a7a6defec8b','teams','demo-3c3cf122',NULL,NULL,NULL,'https://teams.demo/recordings/3c3cf122',NULL,'Payments API outage — incident bridge (all-hands)','Full incident bridge call: detection, rollback decision, and recovery confirmation.','2026-06-27T12:05:00','2026-06-27T13:05:00',3600,'6da32b93-6f3d-5f80-b6e7-69cba3f13e38','mgr@acme.demo',NULL,NULL,'[{"name": "Support Agent", "email": "mgr@acme.demo", "role": "organizer", "internal": true}]'::jsonb,'not_required','normal','ticket_team_only','2027-07-29T12:00:00','external_reference',NULL,'linked','completed','Incident bridge for the Payments API outage: on-call engineer identified a bad config deploy within 6 minutes of paging, IC approved an immediate rollback, and payments traffic recovered within ~40 minutes. No canary stage existed to catch the bad config pre-rollout; action item raised to add one.','[{"title": "Add canary stage to payments deploy pipeline", "owner_suggestion": "lead", "confidence": 0.91}]'::jsonb,'6da32b93-6f3d-5f80-b6e7-69cba3f13e38','2026-06-27T12:05:00','2026-07-29T06:00:00')
