INSERT INTO incident_retrospectives (id,tenant_id,incident_id,summary,status,is_rca_governed,source_type,source_ticket_id,rca_number,severity,owner_id,approver_id,team_id,trigger_policy_id,previous_status,due_at,submitted_at,approved_at,executive_summary,customer_impact,technical_summary,root_cause_statement,root_cause_category,contributing_factor_tags,detection_gap,prevention_plan,lessons_learned,ai_draft_status,ai_confidence,ai_model_version,created_by) VALUES
('3aa666ec-85fe-5825-9f17-78bf3e21e62d','56cc885c-37d4-5dc6-900d-1a7a6defec8b',NULL,'Recurring 3rd-floor packet loss traced to a failing SFP module.','actions_in_progress',true,'ticket','ce332e2b-8000-566b-9564-7870a5e7a4c6','RCA-2026-0002','sev3','ba390f71-e0c1-5cb8-8993-20574d961dac','6da32b93-6f3d-5f80-b6e7-69cba3f13e38','b3db1fc9-30e0-51f3-bfe8-1acbee2fb127','04fb5f12-b475-576d-83fe-ce104eda4086','approved','2026-07-25T12:00:00','2026-07-20T12:00:00','2026-07-21T12:00:00','Third recurrence of packet loss on the 3rd-floor switch stack; SLA breached before root cause was found.','Intermittent VoIP/video drops for ~40 staff over 4 days; two dropped customer calls reported.','Packet capture during an active loss event showed a flapping uplink; SFP module on port 14 was degraded, not fully failed, so health checks didn''t catch it.','A degrading (not dead) SFP transceiver caused intermittent link flaps that standard link-up/down monitoring didn''t detect.','environment','["no_proactive_health_check", "hardware_degradation"]'::jsonb,'No signal-quality monitoring on switch uplinks — only up/down state was alerted on.','Add optical signal-strength monitoring to catch degrading transceivers before they flap.','Link up/down monitoring alone misses slow hardware degradation.','completed',0.74,'heuristic-v1','6da32b93-6f3d-5f80-b6e7-69cba3f13e38')
INSERT INTO retro_action_items (id,tenant_id,retro_id,description,title,action_type,priority,owner_id,team_id,due_at,status,verification_method,verified_by,verified_at) VALUES
